ARRAY['standard'],
ARRAY['follicular','ovulation'],
ARRAY['maintain','energy','muscle'],
ARRAY[]::text[],
ARRAY['gluten','eggs','dairy'],
'medium','under_20','medium',
'{"es":["150g espagueti","80g guanciale o bacon en dados","2 yemas + 1 huevo entero","50g pecorino rallado (o mezcla pecorino-parmesano)","Pimienta negra recién molida abundante","Sal para el agua de cocción"],"en":["150g spaghetti","80g guanciale or bacon diced","2 yolks + 1 whole egg","50g grated pecorino (or pecorino-parmesan mix)","Plenty of freshly ground black pepper","Salt for pasta water"]}',
'{"es":["Cuece la pasta al dente en agua muy salada, reserva 1 taza del agua","Dora el guanciale en sartén seca a fuego medio hasta crujiente","Bate las yemas con el huevo entero, el pecorino y abundante pimienta","Mezcla la pasta escurrida con el guanciale fuera del fuego","Añade los huevos y el queso mezclando rápido, añade agua de cocción poco a poco hasta obtener una salsa cremosa","Sirve inmediatamente con más pecorino y pimienta"],"en":["Cook pasta al dente in well-salted water, reserve 1 cup","Brown guanciale in a dry pan over medium heat until crispy","Beat yolks with whole egg, pecorino and plenty of pepper","Toss drained pasta with guanciale off the heat","Add egg mixture tossing quickly, add cooking water little by little until creamy sauce","Serve immediately with more pecorino and pepper"]}'
),

('pollo_asado_domingo_std',394,'dinner','🍗',
'{"es":"Pollo asado al horno del domingo","en":"Sunday roast chicken","fr":"Poulet roti du dimanche","it":"Pollo arrosto della domenica"}',
'{"es":"Pollo entero al horno con mantequilla de hierbas, limón y ajo — el asado de siempre, perfecto","en":"Whole roast chicken with herb butter, lemon and garlic — the timeless perfect roast"}',
