ARRAY['standard','gluten_free'],
ARRAY['follicular','ovulation'],
ARRAY['maintain','muscle','energy'],
ARRAY[]::text[],
ARRAY['dairy'],
'medium','over_40','medium',
'{"es":["1 pollo entero (1,5-1,8 kg)","50g mantequilla blanda","3 dientes de ajo picados","Ralladura y zumo de 1 limón","Romero y tomillo frescos","Sal gruesa, pimienta negra","Aceite de oliva","1 cebolla y 1 limón en mitades (para el interior)"],"en":["1 whole chicken (1.5-1.8 kg)","50g soft butter","3 garlic cloves chopped","Zest and juice of 1 lemon","Fresh rosemary and thyme","Coarse salt, black pepper","Olive oil","1 onion and 1 lemon halved (for cavity)"]}',
'{"es":["Precalienta el horno a 200°C","Mezcla la mantequilla con el ajo, la ralladura de limón y las hierbas","Seca el pollo con papel y coloca en bandeja","Mete la mantequilla de hierbas bajo la piel del pecho","Rellena el interior con la cebolla y el limón cortados","Riega con aceite y zumo de limón, sazona con sal gruesa","Hornea 70-75 min, deja reposar 10 min antes de trinchar"],"en":["Preheat oven to 200°C","Mix butter with garlic, lemon zest and herbs","Pat chicken dry and place in roasting tin","Push herb butter under breast skin","Fill cavity with halved onion and lemon","Drizzle with oil and lemon juice, season with coarse salt","Roast 70-75 min, rest 10 min before carving"]}'
),

('huevos_benedictinos_std',395,'breakfast','🥚',
