'hard','under_20','medium',
'{"es":["2 huevos","2 muffins ingleses partidos","2 lonchas de jamón cocido o york","Para la holandesa: 2 yemas, 80g mantequilla clarificada, 1 cda zumo de limón, sal, pimienta de cayena","1 cda vinagre blanco","Cebollino para decorar"],"en":["2 eggs","2 English muffins halved","2 slices cooked ham","For hollandaise: 2 yolks, 80g clarified butter, 1 tbsp lemon juice, salt, cayenne","1 tbsp white vinegar","Chives to garnish"]}',
'{"es":["Prepara la holandesa al baño María: bate las yemas con el limón, añade la mantequilla en hilo hasta emulsionar, sazona","Tuesta los muffins y calienta el jamón","Escalfa los huevos en agua con vinagre 3 min","Monta: muffin, jamón, huevo escalfado, holandesa generosa y cebollino"],"en":["Make hollandaise in a double boiler: whisk yolks with lemon, add butter in a stream until emulsified, season","Toast muffins and warm ham","Poach eggs in water with vinegar 3 min","Build: muffin, ham, poached egg, generous hollandaise and chives"]}'
),

('risotto_setas_std',396,'dinner','🍄',
