ARRAY[]::text[],
ARRAY['dairy'],
'medium','20_40','medium',
'{"es":["300g arroz arborio","300g setas mixtas (shiitake, portobello, champiñón)","1 cebolla en dados","2 dientes de ajo","150ml vino blanco seco","1L caldo de verduras caliente","60g parmesano rallado","2 cdas mantequilla","2 cdas aceite de oliva","Tomillo fresco","Sal, pimienta negra"],"en":["300g arborio rice","300g mixed mushrooms (shiitake, portobello, button)","1 onion diced","2 garlic cloves","150ml dry white wine","1L hot vegetable stock","60g grated parmesan","2 tbsp butter","2 tbsp olive oil","Fresh thyme","Salt, black pepper"]}',
'{"es":["Sofríe la cebolla y el ajo en aceite y mantequilla 4 min","Añade las setas y cocina 5 min hasta que suelten el agua","Incorpora el arroz y tuesta 2 min","Vierte el vino y deja evaporar","Añade el caldo caliente cucharón a cucharón, removiendo siempre, durante 20 min","Retira del fuego, añade el parmesano y la mantequilla restante, mezcla bien","Sirve con tomillo fresco y pimienta"],"en":["Sauté onion and garlic in oil and butter 4 min","Add mushrooms and cook 5 min until they release water","Add rice and toast 2 min","Pour wine and let evaporate","Add hot stock ladle by ladle, stirring constantly, for 20 min","Remove from heat, add parmesan and remaining butter, stir well","Serve with fresh thyme and pepper"]}'
),

